function countCircles(knows: number[][]): number {
  const n = knows.length, seen = new Array(n).fill(false);
  let circles = 0;
  for (let i = 0; i < n; i++) {
    if (seen[i]) continue;
    circles++;
    seen[i] = true;
    const stack = [i];
    while (stack.length) {
      const u = stack.pop()!;
      for (let v = 0; v < n; v++)
        if (knows[u][v] === 1 && !seen[v]) { seen[v] = true; stack.push(v); }
    }
  }
  return circles;
}

