class Solution:
    def countCircles(self, knows: List[List[int]]) -> int:
        n = len(knows)
        seen = [False] * n
        circles = 0
        for i in range(n):
            if seen[i]:
                continue
            circles += 1
            seen[i] = True
            stack = [i]
            while stack:
                u = stack.pop()
                for v in range(n):
                    if knows[u][v] == 1 and not seen[v]:
                        seen[v] = True
                        stack.append(v)
        return circles

