        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        groups = n
        for i in range(n):
            for j in range(i + 1, n):
                if knows[i][j] == 1:
                    a, b = find(i), find(j)
                    if a != b:
                        parent[a] = b
                        groups -= 1
        return groups

